#define PI 3.141592654
#define e 2.7182818284
vec2 eToIP(vec2 p)
{
    // e^p
    float ep=pow(e,p.x);
    return ep*vec2(cos(p.y),sin(p.y));
}

vec2 iSqu(vec2 p)
{
    // p*p
    return vec2(p.x*p.x-p.y*p.y,2.*p.x*p.y);
}

vec2 isin(vec2 p)
{
    return vec2(sin(2.*PI*p.x),sin(2.*PI*p.y));
}

vec2 iMulti(vec2 p,vec2 q)
{
    // p*q
    return vec2(p.x*q.x-p.y*q.y,p.x*q.y+p.y*q.x);
}

vec2 iiPow(vec2 p, int i)
{
    // p^int(i)
    int j=2;
    vec2 f=iSqu(p);
    while(j<i)
    {
        f=iMulti(f,p);
        j++;
    }
    return f;
}

vec2 iInv(vec2 p)
{
    // 1/p
    float s=1./(p.x*p.x+p.y*p.y);
    return s*vec2(p.x,-p.y);
}

vec2 iDiv(vec2 p, vec2 q)
{
    // p/q
    return(iMulti(p,iInv(q)));
}

