vec2 g(vec2 p,float h)
{
    //derivative of f (numerical)
    vec2 fp=f(p);
    vec2 fx=f(p+vec2(h));
    return vec2((fx-fp)/h);
}

vec2 newt(vec2 init, float d)
{
    //speed of fractal splitting
    float sp=.66;
    int ma=int(iTime*sp);
    int i=0;
    while(i<ma)
    {
        init=init-iDiv(f(init),g(init,d));
        i++;
    }
    vec2 init2=init-iDiv(f(init),g(init,d));
    return mix(init,init2,fract(iTime*sp));
}

